  "acheteur": { "nom": string|null, "siren": string|null, "siret": string|null, "tvaIntracom": string|null, "adresse": { "ligne1": string|null, "codePostal": string|null, "ville": string|null, "pays": string|null } },
  "lignes": [ { "designation": string, "quantite": number, "prixUnitaireHT": number, "tauxTVA": number } ],
  "totaux": { "totalHT": number|null, "totalTVA": number|null, "totalTTC": number|null, "netAPayer": number|null },
  "acomptes": [ { "montant": number, "date": "YYYY-MM-DD"|null, "libelle": string|null } ],
  "paiementsAnterieurs": [ { "montant": number, "date": "YYYY-MM-DD"|null, "libelle": string|null } ],
